/**
 * The words for the AI allowance: the line that says it ran out and when it
 * comes back, and the quiet "3 AI cards left today". Exact when the server
 * gave numbers, and true without them: a rest whose kind is unknown never
 * names a day, because it might be the month's.
 */
import { t } from '@/i18n/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { aiCardsLeft, aiRest, type AiRest, type CardsLeft } from './quota.js';

/** "3:30 AM" in the reader's own clock and locale. */
export function clockTime(when: Date): string {
  return when.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
}

/** "1 November" in the reader's own calendar and locale. */
export function dayAndMonth(when: Date): string {
  return when.toLocaleDateString(undefined, { day: 'numeric', month: 'long' });
}

/** What the screen says while AI cards rest. */
export function restLine(rest: AiRest): string {
  if (rest.kind === 'day') {
    const time = clockTime(rest.until);
    return rest.limit === undefined
      ? t('ai.restDayNoLimit', { time })
      : t('ai.restDay', { limit: rest.limit, time });
  }
  if (rest.kind === 'month') {
    const date = dayAndMonth(rest.until);
    return rest.limit === undefined
      ? t('ai.restMonthNoLimit', { date })
      : t('ai.restMonth', { limit: rest.limit, date });
  }
  return t('ai.restUnknown');
}

/** "3 AI cards left today", or "… this month" when the month is the nearer end. */
export function leftLine(left: CardsLeft): string {
  return t(left.period === 'day' ? 'ai.leftDay' : 'ai.leftMonth', { count: left.left });
}

/**
 * The rest and the cards left, read from IndexedDB so they draw on the first
 * frame and change as soon as a card or a refusal is recorded. `undefined`
 * for either means "not resting" or "not known".
 */
export function useAiAllowance(): { rest: AiRest | undefined; left: CardsLeft | undefined } {
  const rest = useLiveQuery(() => aiRest(), undefined, []);
  const left = useLiveQuery(() => aiCardsLeft(), undefined, []);
  return { rest, left };
}
